public class CompoundAssignment {
    public static void main(String[] args) {
        int x = 10;
        System.out.println("Initial: " + x);

        x += 5;  // x = x + 5
        System.out.println("After +=: " + x);  // 15

        x -= 3;  // x = x - 3
        System.out.println("After -=: " + x);  // 12

        x *= 2;  // x = x * 2
        System.out.println("After *=: " + x);  // 24

        x /= 4;  // x = x / 4
        System.out.println("After /=: " + x);  // 6

        x %= 4;  // x = x % 4
        System.out.println("After %=: " + x);  // 2
    }
}

public class IncrementDemo {
    public static void main(String[] args) {
        // Pre-increment
        int i = 5;
        System.out.println(++i);  // 6 (increment first)
        System.out.println(i);    // 6

        // Post-increment
        int j = 5;
        System.out.println(j++);  // 5 (use first)
        System.out.println(j);    // 6

        // Comparison
        int a = 5, b = 5;
        int x = ++a;  // a=6, x=6
        int y = b++;  // b=6, y=5
        System.out.println("a=" + a + ", x=" + x);  // 6, 6
        System.out.println("b=" + b + ", y=" + y);  // 6, 5
    }
}

public class PrecedenceDemo {
    public static void main(String[] args) {
        // Without parentheses
        int r1 = 5 + 3 * 2;
        System.out.println(r1);  // 11 (* before +)

        // With parentheses
        int r2 = (5 + 3) * 2;
        System.out.println(r2);  // 16 (+ first)

        // Complex expression
        int a = 10, b = 5, c = 2;
        int r3 = a + b * c - 3;
        System.out.println(r3);  // 17
        // 5*2=10, 10+10=20, 20-3=17

        // Logical operators
        boolean r4 = true || false && false;
        System.out.println(r4);  // true (&& first)
    }
}
